import random
import re


_ALPHABET = "abcdefghijklmnopqrstuvwxyz"
_SMALL_CASES = (
    "-",
    "a",
    "--\n--",
    "-a\n--",
    "-a-\n--a\n---",
    "-a-\n--b\n---",
    "-a--\n--b-\n---a\n----",
    "ab--\n--b-\n---a\nc---",
    "us---\n-st--\n--s--\nu--s-\n---ts",
    "aaa\naaa\naaa",
    "---\n---\n---",
)
_REFERENCE_WALK_LIMIT = 500_000


def _integer(token: str) -> int | None:
    if re.fullmatch(r"[+-]?[0-9]+", token) is None:
        return None
    digits = token.lstrip("+-").lstrip("0") or "0"
    magnitude = int(digits) if len(digits) <= 5 else 100_000
    return -magnitude if token.startswith("-") else magnitude


def _input_rows(inp: str) -> list[str] | None:
    lines = inp.splitlines()
    if not lines:
        return None
    size = _integer(lines[0].strip(" \t"))
    if size is None or not 1 <= size <= 100 or len(lines) != size + 1:
        return None
    rows = lines[1:]
    if any(len(row) != size or re.fullmatch(r"[a-z-]+", row) is None
           for row in rows):
        return None
    return rows


def _format_input(rows: list[str]) -> str:
    return str(len(rows)) + "\n" + "\n".join(rows) + "\n"


def validate_input(inp: str) -> bool:
    return _input_rows(inp) is not None


def gen_small(seed: int, n: int) -> list[str]:
    rng = random.Random(seed)
    cases = [_format_input(case.splitlines()) for case in _SMALL_CASES[:n]]
    while len(cases) < n:
        size = rng.randint(2, 7)
        choices = rng.choice(("-aa", "---ab", "--abc", "-abc", "ab"))
        rows = [
            "".join(rng.choice(choices) for _ in range(size))
            for _ in range(size)
        ]
        cases.append(_format_input(rows))
    return cases


def gen_stress(seed: int) -> list[str]:
    rng = random.Random(seed)
    size = 100
    cluster_end = 88
    dense = [["-"] * size for _ in range(size)]
    for i in range(size):
        for j in range(size):
            if (i < cluster_end) == (j < cluster_end):
                dense[i][j] = rng.choice("aaaaaaaa-b")
    dense[rng.randrange(cluster_end)][rng.randrange(cluster_end, size)] = "b"

    # A cross-cycle palindrome has equally many a's on either side of its b.
    cycle_split = 49
    cycles = [["-"] * size for _ in range(size)]
    for start, end in ((0, cycle_split), (cycle_split, size)):
        for i in range(start, end):
            successor = start + (i - start + 1) % (end - start)
            cycles[i][successor] = "a"
    cycles[rng.randrange(cycle_split)][rng.randrange(cycle_split, size)] = "b"

    return [_format_input(["".join(row) for row in graph])
            for graph in (dense, cycles)]


def check_postconditions(inp: str, out: str) -> list[tuple[str, str]]:
    rows = _input_rows(inp)
    if rows is None:
        return [("POST-1", "Input does not have the required graph format.")]
    size = len(rows)
    lines = out.splitlines()
    if len(lines) != size:
        return [("POST-2", f"Expected {size} output rows, got {len(lines)}.")]

    answers = []
    for i, line in enumerate(lines, 1):
        tokens = line.split()
        if len(tokens) != size:
            return [("POST-2", f"Row {i} must contain {size} integers.")]
        values = [_integer(token) for token in tokens]
        if None in values:
            return [("POST-2", f"Row {i} contains a non-integer token.")]
        answers.append(values)

    outgoing = [{} for _ in rows]
    incoming = [{} for _ in rows]
    for i, row in enumerate(rows):
        for j, label in enumerate(row):
            if label != "-":
                outgoing[i][label] = outgoing[i].get(label, 0) | (1 << j)
                incoming[j][label] = incoming[j].get(label, 0) | (1 << i)

    failures = []
    limit = 2 * size * size - 1
    for i, row in enumerate(rows):
        for j, label in enumerate(row):
            value = answers[i][j]
            pair = f"({i + 1}, {j + 1})"
            if not -1 <= value <= limit:
                failures.append(("POST-3", f"{pair} is outside the answer bounds."))
            elif i == j:
                if value != 0:
                    failures.append(("POST-4", f"{pair} must be 0."))
            elif label != "-":
                if value != 1:
                    failures.append(("POST-4", f"{pair} has a direct edge and must be 1."))
            elif value in (0, 1):
                failures.append(("POST-4", f"{pair} cannot have length {value}."))
            else:
                common = outgoing[i].keys() & incoming[j].keys()
                has_two = any(outgoing[i][c] & incoming[j][c] for c in common)
                if has_two and value != 2:
                    failures.append(("POST-5", f"{pair} has a palindrome walk of length 2."))
                elif not has_two and value == 2:
                    failures.append(("POST-5", f"{pair} has no palindrome walk of length 2."))
                elif value > 2 and not common:
                    failures.append(("POST-5", f"{pair} has no matching endpoint labels."))
    return failures


def metamorphic_pairs(seed: int, n: int) -> list[tuple[str, str, str, str]]:
    if n <= 0:
        return []
    rng = random.Random(seed)
    pairs = []
    for original in gen_small(seed, n + len(_SMALL_CASES)):
        shift = rng.randrange(1, len(_ALPHABET))
        renamed = _ALPHABET[shift:] + _ALPHABET[:shift]
        transformed = original.translate(str.maketrans(_ALPHABET, renamed))
        if transformed != original:
            pairs.append(("POST-6", "equal", original, transformed))
        if len(pairs) == n:
            break
    return pairs


def reference_small(inp: str) -> str | None:
    rows = _input_rows(inp)
    if rows is None or len(rows) > 8:
        return None
    size = len(rows)
    edges = [
        [(j, label) for j, label in enumerate(row) if label != "-"]
        for row in rows
    ]

    # The nested subwalks of a shortest palindrome have distinct endpoint
    # pairs. Each noncentral pair has distinct vertices and no direct edge,
    # since either condition would allow a shorter replacement.
    missing_pairs = sum(
        i != j and label == "-"
        for i, row in enumerate(rows)
        for j, label in enumerate(row)
    )
    length_limit = 2 * missing_pairs + 1
    remaining_budget = _REFERENCE_WALK_LIMIT
    answers = []
    for start in range(size):
        distances = [-1] * size
        distances[start] = 0
        unanswered = size - 1
        walks = [(start, "")]
        for length in range(1, length_limit + 1):
            if not walks or not unanswered:
                break
            extensions = []
            for vertex, word in walks:
                for end, label in edges[vertex]:
                    if remaining_budget == 0:
                        return None
                    remaining_budget -= 1
                    extended_word = word + label
                    if distances[end] == -1 and extended_word == extended_word[::-1]:
                        distances[end] = length
                        unanswered -= 1
                    if length < length_limit:
                        extensions.append((end, extended_word))
                if not unanswered:
                    break
            walks = extensions
        answers.append(" ".join(map(str, distances)))
    return "\n".join(answers) + "\n"
